def measurement_mapping(bitstring: str) -> dict[str, int]:
    """Map q0/q1 to integer measurement results from a two-bit string.

    Input ordering is q1q0, so the rightmost bit is q0.
    """
    if len(bitstring) != 2 or any(ch not in "01" for ch in bitstring):
        raise ValueError("expected a two-bit measurement string")
    return {"q0": int(bitstring[1]), "q1": int(bitstring[0])}

def teleportation_corrections(m0: int, m1: int) -> list[str]:
    """Return the Pauli corrections to apply for teleportation measurement bits (m0, m1).

    m0 controls the X correction and m1 controls the Z correction.
    The returned list is ordered as operations to apply.
    """
    if m0 not in (0, 1) or m1 not in (0, 1):
        raise ValueError("measurement bits must be 0 or 1")

    ops: list[str] = []
    if m1 == 1:
        ops.append("Z")
    if m0 == 1:
        ops.append("X")
    return ops

import time
import functools
from typing import Any, Callable


def retry(
    max_attempts: int = 3,
    base_delay: float = 0.0,
    backoff_factor: float = 2.0,
    exceptions: tuple[type[Exception], ...] = (Exception,),
) -> Callable:
    """Decorator that retries a function on specified exceptions.

    - max_attempts: total attempts (1 = no retry)
    - base_delay: initial delay in seconds between retries
    - backoff_factor: multiply delay by this after each retry
    - exceptions: tuple of exception types to catch

    Raises the last exception if all attempts fail.
    """
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            delay = base_delay
            last_exc: Exception | None = None
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt < max_attempts - 1:
                        if delay > 0:
                            time.sleep(delay)
                        delay *= backoff_factor
            raise last_exc  # type: ignore[misc]
        return wrapper
    return decorator

def apply_patches(base_state: dict[str, dict], patches: list[dict]) -> dict:
    """Apply ordered key/value patches with duplicate suppression and conflict reporting.

    Input:
      base_state: {key: {"value": object, "version": int}}
      patches: list of {
          "patch_id": str,
          "key": str,
          "expected_version": int,
          "value": object,
          "new_version": int,
      }

    Output:
      {
        "state": {key: {"value": object, "version": int}},
        "applied_patch_ids": [patch ids in first-application order],
        "conflicts": [
            {
              "patch_id": str,
              "key": str,
              "reason": "missing_key" | "version_mismatch" | "non_monotonic_version",
              "expected_version": int,
              "actual_version": int | None,
              "attempted_new_version": int,
            }, ...
        ],
      }

    Rules:
    - Do not mutate inputs.
    - Ignore duplicate patch_ids after their first occurrence, whether the first occurrence applied cleanly or conflicted.
    - A patch applies only if the key exists, expected_version matches the current version, and new_version > current version.
    - Conflicts must be reported in encounter order.
    - Output state keys and nested records should be ordinary dicts.
    """
    state = {
        key: {"value": record["value"], "version": record["version"]}
        for key, record in base_state.items()
    }
    seen_patch_ids = set()
    applied_patch_ids = []
    conflicts = []

    for patch in patches:
        patch_id = patch["patch_id"]
        if patch_id in seen_patch_ids:
            continue
        seen_patch_ids.add(patch_id)

        key = patch["key"]
        expected_version = patch["expected_version"]
        attempted_new_version = patch["new_version"]

        if key not in state:
            conflicts.append(
                {
                    "patch_id": patch_id,
                    "key": key,
                    "reason": "missing_key",
                    "expected_version": expected_version,
                    "actual_version": None,
                    "attempted_new_version": attempted_new_version,
                }
            )
            continue

        actual_version = state[key]["version"]
        if actual_version != expected_version:
            conflicts.append(
                {
                    "patch_id": patch_id,
                    "key": key,
                    "reason": "version_mismatch",
                    "expected_version": expected_version,
                    "actual_version": actual_version,
                    "attempted_new_version": attempted_new_version,
                }
            )
            continue

        if attempted_new_version <= actual_version:
            conflicts.append(
                {
                    "patch_id": patch_id,
                    "key": key,
                    "reason": "non_monotonic_version",
                    "expected_version": expected_version,
                    "actual_version": actual_version,
                    "attempted_new_version": attempted_new_version,
                }
            )
            continue

        state[key] = {
            "value": patch["value"],
            "version": attempted_new_version,
        }
        applied_patch_ids.append(patch_id)

    return {
        "state": state,
        "applied_patch_ids": applied_patch_ids,
        "conflicts": conflicts,
    }

def apply_events(events):
    state = {"active": {}, "history": []}

    for event in events:
        kind = event["type"]
        session_id = event["session_id"]

        if kind == "start":
            if session_id in state["active"]:
                raise ValueError(f"session already active: {session_id}")
            state["active"][session_id] = {
                "user": event["user"],
                "started_at": event["ts"],
                "last_seen": event["ts"],
                "messages": 0,
            }
            continue

        if session_id not in state["active"]:
            raise ValueError(f"session not active: {session_id}")

        if kind == "message":
            active = state["active"][session_id]
            active["messages"] += 1
            active["last_seen"] = event["ts"]
            continue

        if kind == "end":
            active = state["active"].pop(session_id)
            state["history"].append(
                {
                    "session_id": session_id,
                    "user": active["user"],
                    "started_at": active["started_at"],
                    "ended_at": event["ts"],
                    "messages": active["messages"],
                }
            )
            continue

        raise ValueError(f"unknown event type: {kind}")

    state["history"].sort(key=lambda item: (item["started_at"], item["session_id"]))
    return state

