def deserialize(data: str) -> TreeNode | None:
    """Deserialize a JSON string back to an n-ary tree."""
    if data == "null":
        return None

    obj = json.loads(data)

    def from_dict(d: dict) -> TreeNode:
        return TreeNode(
            value=d["v"],
            children=[from_dict(ch) for ch in d.get("c", [])],
