def _normalize_pauli(label: str) -> str:
    normalized = label.strip().upper()
    if normalized not in {"I", "X", "Y", "Z"}:
        raise ValueError(f"unsupported Pauli operator: {label!r}")
    return normalized


_CONJUGATION_RULES = {
    "H": {
        "I": (1, "I"),
        "X": (1, "Z"),
        "Y": (-1, "Y"),
        "Z": (1, "X"),
    },
    "S": {
        "I": (1, "I"),
        "X": (1, "Y"),
        "Y": (-1, "X"),
        "Z": (1, "Z"),
    },
    "SDG": {
        "I": (1, "I"),
        "X": (-1, "Y"),
        "Y": (1, "X"),
        "Z": (1, "Z"),
    },
}


def apply_gate_sequence(pauli: str, gates: list[str]) -> tuple[int, str]:
    """Update a signed single-qubit Pauli under Clifford conjugation."""
    raw = pauli.strip()
    sign = -1 if raw.startswith("-") else 1
    label = raw[1:] if raw.startswith("-") else raw
    label = _normalize_pauli(label)

    for gate in gates:
        gate_name = gate.strip().upper()
        if gate_name not in _CONJUGATION_RULES:
            raise ValueError(f"unsupported gate: {gate!r}")
        gate_sign, next_label = _CONJUGATION_RULES[gate_name][label]
        sign *= gate_sign
        label = next_label

    return sign, label

def normalize_identifier(raw: str) -> str:
    """Return a lowercase snake_case identifier built from a human label.

    Rules:
    - Trim leading/trailing whitespace.
    - Convert internal runs of whitespace or hyphens to a single underscore.
    - Remove any characters that are not ASCII letters, digits, underscores, spaces, or hyphens.
    - Collapse repeated underscores.
    """
    cleaned = []
    for char in raw.strip().lower():
        if char.isascii() and (char.isalnum() or char in {"_", " ", "-"}):
            cleaned.append(char)

    text = "".join(cleaned).replace("-", "_").replace(" ", "_")
    while "__" in text:
        text = text.replace("__", "_")
    return text.strip("_")

import time
import functools
from typing import Any, Callable


def retry(
    max_attempts: int = 3,
    base_delay: float = 0.0,
    backoff_factor: float = 2.0,
    exceptions: tuple[type[Exception], ...] = (Exception,),
) -> Callable:
    """Decorator that retries a function on specified exceptions.

    - max_attempts: total attempts (1 = no retry)
    - base_delay: initial delay in seconds between retries
    - backoff_factor: multiply delay by this after each retry
    - exceptions: tuple of exception types to catch

    Raises the last exception if all attempts fail.
    """
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            delay = base_delay
            last_exc: Exception | None = None
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt < max_attempts - 1:
                        if delay > 0:
                            time.sleep(delay)
                        delay *= backoff_factor
            raise last_exc  # type: ignore[misc]
        return wrapper
    return decorator

def teleportation_corrections(m0: int, m1: int) -> list[str]:
    """Return the Pauli corrections to apply for teleportation measurement bits (m0, m1).

    m0 controls the X correction and m1 controls the Z correction.
    The returned list is ordered as operations to apply.
    """
    if m0 not in (0, 1) or m1 not in (0, 1):
        raise ValueError("measurement bits must be 0 or 1")

    ops: list[str] = []
    if m1 == 1:
        ops.append("Z")
    if m0 == 1:
        ops.append("X")
    return ops

import cmath


def qft_basis_state(n_qubits: int, basis_index: int) -> list[complex]:
    """Return the exact QFT statevector for computational basis |basis_index>."""
    if n_qubits <= 0:
        raise ValueError("n_qubits must be positive")
    dimension = 1 << n_qubits
    if not 0 <= basis_index < dimension:
        raise ValueError("basis_index out of range")

    scale = dimension ** -0.5
    return [
        scale * cmath.exp(2j * cmath.pi * basis_index * output_index / dimension)
        for output_index in range(dimension)
    ]

