def apply_events(events):
    state = {"active": {}, "history": []}

    for event in events:
        kind = event["type"]
        session_id = event["session_id"]

        if kind == "start":
            if session_id in state["active"]:
                raise ValueError(f"session already active: {session_id}")
            state["active"][session_id] = {
                "user": event["user"],
                "started_at": event["ts"],
                "last_seen": event["ts"],
                "messages": 0,
            }
            continue

        if session_id not in state["active"]:
            raise ValueError(f"session not active: {session_id}")

        if kind == "message":
            active = state["active"][session_id]
            active["messages"] += 1
            active["last_seen"] = event["ts"]
            continue

        if kind == "end":
            active = state["active"].pop(session_id)
            state["history"].append(
                {
                    "session_id": session_id,
                    "user": active["user"],
                    "started_at": active["started_at"],
                    "ended_at": event["ts"],
                    "messages": active["messages"],
                }
            )
            continue

        raise ValueError(f"unknown event type: {kind}")

    state["history"].sort(key=lambda item: (item["started_at"], item["session_id"]))
    return state

def apply_patches(base_state: dict[str, dict], patches: list[dict]) -> dict:
    """Apply ordered key/value patches with duplicate suppression and conflict reporting.

    Input:
      base_state: {key: {"value": object, "version": int}}
      patches: list of {
          "patch_id": str,
          "key": str,
          "expected_version": int,
          "value": object,
          "new_version": int,
      }

    Output:
      {
        "state": {key: {"value": object, "version": int}},
        "applied_patch_ids": [patch ids in first-application order],
        "conflicts": [
            {
              "patch_id": str,
              "key": str,
              "reason": "missing_key" | "version_mismatch" | "non_monotonic_version",
              "expected_version": int,
              "actual_version": int | None,
              "attempted_new_version": int,
            }, ...
        ],
      }

    Rules:
    - Do not mutate inputs.
    - Ignore duplicate patch_ids after their first occurrence, whether the first occurrence applied cleanly or conflicted.
    - A patch applies only if the key exists, expected_version matches the current version, and new_version > current version.
    - Conflicts must be reported in encounter order.
    - Output state keys and nested records should be ordinary dicts.
    """
    state = {
        key: {"value": record["value"], "version": record["version"]}
        for key, record in base_state.items()
    }
    seen_patch_ids = set()
    applied_patch_ids = []
    conflicts = []

    for patch in patches:
        patch_id = patch["patch_id"]
        if patch_id in seen_patch_ids:
            continue
        seen_patch_ids.add(patch_id)

        key = patch["key"]
        expected_version = patch["expected_version"]
        attempted_new_version = patch["new_version"]

        if key not in state:
            conflicts.append(
                {
                    "patch_id": patch_id,
                    "key": key,
                    "reason": "missing_key",
                    "expected_version": expected_version,
                    "actual_version": None,
                    "attempted_new_version": attempted_new_version,
                }
            )
            continue

        actual_version = state[key]["version"]
        if actual_version != expected_version:
            conflicts.append(
                {
                    "patch_id": patch_id,
                    "key": key,
                    "reason": "version_mismatch",
                    "expected_version": expected_version,
                    "actual_version": actual_version,
                    "attempted_new_version": attempted_new_version,
                }
            )
            continue

        if attempted_new_version <= actual_version:
            conflicts.append(
                {
                    "patch_id": patch_id,
                    "key": key,
                    "reason": "non_monotonic_version",
                    "expected_version": expected_version,
                    "actual_version": actual_version,
                    "attempted_new_version": attempted_new_version,
                }
            )
            continue

        state[key] = {
            "value": patch["value"],
            "version": attempted_new_version,
        }
        applied_patch_ids.append(patch_id)

    return {
        "state": state,
        "applied_patch_ids": applied_patch_ids,
        "conflicts": conflicts,
    }

from dataclasses import dataclass
from typing import Any, Optional


@dataclass(frozen=True)
class ConflictRecord:
    patch_id: str
    key: str
    reason: str
    expected_version: int
    actual_version: Optional[int]
    attempted_new_version: int


@dataclass(frozen=True)
class ApplyResult:
    state: dict[str, dict[str, Any]]
    applied_patch_ids: list[str]
    conflicts: list[ConflictRecord]


def apply_patch_plan(base_state, patches):
    state = {key: value.copy() for key, value in base_state.items()}
    applied_patch_ids = []
    conflicts = []
    seen_patch_ids = set()

    for patch in patches:
        patch_id = patch["patch_id"]
        if patch_id in seen_patch_ids:
            continue
        seen_patch_ids.add(patch_id)

        key = patch["key"]
        current = state.get(key)
        if current is None:
            conflicts.append(
                ConflictRecord(
                    patch_id=patch_id,
                    key=key,
                    reason="missing_key",
                    expected_version=patch["expected_version"],
                    actual_version=None,
                    attempted_new_version=patch["new_version"],
                )
            )
            continue

        current_version = current["version"]
        if current_version != patch["expected_version"]:
            conflicts.append(
                ConflictRecord(
                    patch_id=patch_id,
                    key=key,
                    reason="version_mismatch",
                    expected_version=patch["expected_version"],
                    actual_version=current_version,
                    attempted_new_version=patch["new_version"],
                )
            )
            continue

        if patch["new_version"] <= current_version:
            conflicts.append(
                ConflictRecord(
                    patch_id=patch_id,
                    key=key,
                    reason="non_monotonic_version",
                    expected_version=patch["expected_version"],
                    actual_version=current_version,
                    attempted_new_version=patch["new_version"],
                )
            )
            continue

        state[key] = {"value": patch["value"], "version": patch["new_version"]}
        applied_patch_ids.append(patch_id)

    return ApplyResult(state=state, applied_patch_ids=applied_patch_ids, conflicts=conflicts)


def apply_patches(base_state, patches):
    result = apply_patch_plan(base_state, patches)
    return {
        "state": result.state,
        "applied_patch_ids": result.applied_patch_ids,
        "conflicts": [
            {
                "patch_id": conflict.patch_id,
                "key": conflict.key,
                "reason": conflict.reason,
                "expected_version": conflict.expected_version,
                "actual_version": conflict.actual_version,
                "attempted_new_version": conflict.attempted_new_version,
            }
            for conflict in result.conflicts
        ],
    }


def render_conflict_report(result):
    conflicts = result["conflicts"]
    return {
        "applied_count": len(result["applied_patch_ids"]),
        "applied_patch_ids": list(result["applied_patch_ids"]),
        "conflict_count": len(conflicts),
        "conflict_keys": [conflict["key"] for conflict in conflicts],
